let activeUtterance: SpeechSynthesisUtterance | null = null;
let queuedSpeakTimer: number | null = null;
let cachedVoices: SpeechSynthesisVoice[] = [];
let voicesListenerRegistered = false;
let lastSpeechError: string | null = null;
let lastSpeechEvent = 'idle';
let pendingVoicesText: string | null = null;
const debugListeners = new Set<(state: SpeechDebugState) => void>();

const PREFERRED_VOICE_NAMES = ['Joana', 'Luciana', 'Eddy', 'Flo', 'Grandma', 'Grandpa', 'Reed', 'Rocko', 'Sandy', 'Shelley'];

function isChromeBrowser(): boolean {
  return /Chrome/i.test(window.navigator.userAgent) && !/Edg|OPR|CriOS/i.test(window.navigator.userAgent);
}

export interface SpeechDebugState {
  supported: boolean;
  voicesCount: number;
  preferredVoiceName: string | null;
  preferredVoiceLang: string | null;
  availableVoiceNames: string[];
  speaking: boolean;
  pending: boolean;
  paused: boolean;
  lastEvent: string;
  lastError: string | null;
}

function emitDebugState(): void {
  const state = getSpeechDebugState();
  for (const listener of debugListeners) listener(state);
}

function ensureVoicesLoaded(): SpeechSynthesisVoice[] {
  if (cachedVoices.length === 0) {
    cachedVoices = window.speechSynthesis.getVoices();
  }

  return cachedVoices;
}

function refreshVoices(): SpeechSynthesisVoice[] {
  cachedVoices = window.speechSynthesis.getVoices();

  if (pendingVoicesText && cachedVoices.length > 0) {
    const text = pendingVoicesText;
    pendingVoicesText = null;
    window.setTimeout(() => doSpeak(text), 0);
  }

  emitDebugState();
  return cachedVoices;
}

function getPreferredVoice(): SpeechSynthesisVoice | null {
  const voices = ensureVoicesLoaded();

  if (isChromeBrowser()) {
    return (
      voices.find((voice) => voice.default && voice.lang.toLowerCase().startsWith('pt')) ??
      voices.find((voice) => voice.lang.toLowerCase() === 'pt-br') ??
      voices.find((voice) => voice.lang.toLowerCase() === 'pt-pt') ??
      voices.find((voice) => voice.lang.toLowerCase().startsWith('pt')) ??
      null
    );
  }

  for (const preferredName of PREFERRED_VOICE_NAMES) {
    const match = voices.find((voice) => voice.name.toLowerCase() === preferredName.toLowerCase());
    if (match) return match;
  }

  return (
    voices.find((voice) => voice.lang.toLowerCase() === 'pt-pt') ??
    voices.find((voice) => voice.lang.toLowerCase() === 'pt-br') ??
    voices.find((voice) => voice.lang.toLowerCase().startsWith('pt')) ??
    voices.find((voice) => voice.default) ??
    null
  );
}

export function preloadVoices(): void {
  if (!('speechSynthesis' in window)) return;

  refreshVoices();

  if (voicesListenerRegistered) return;

  window.speechSynthesis.addEventListener('voiceschanged', refreshVoices);
  voicesListenerRegistered = true;
  emitDebugState();
}

export function getSpeechDebugState(): SpeechDebugState {
  if (!('speechSynthesis' in window)) {
    return {
      supported: false,
      voicesCount: 0,
      preferredVoiceName: null,
      preferredVoiceLang: null,
      availableVoiceNames: [],
      speaking: false,
      pending: false,
      paused: false,
      lastEvent: lastSpeechEvent,
      lastError: lastSpeechError,
    };
  }

  const synth = window.speechSynthesis;
  const preferredVoice = getPreferredVoice();
  const voices = ensureVoicesLoaded();

  return {
    supported: true,
    voicesCount: voices.length,
    preferredVoiceName: preferredVoice?.name ?? null,
    preferredVoiceLang: preferredVoice?.lang ?? null,
    availableVoiceNames: voices
      .filter((voice) => voice.lang.toLowerCase().startsWith('pt'))
      .slice(0, 6)
      .map((voice) => `${voice.name} (${voice.lang})`),
    speaking: synth.speaking,
    pending: synth.pending,
    paused: synth.paused,
    lastEvent: lastSpeechEvent,
    lastError: lastSpeechError,
  };
}

export function subscribeSpeechDebug(listener: (state: SpeechDebugState) => void): () => void {
  debugListeners.add(listener);
  listener(getSpeechDebugState());
  return () => {
    debugListeners.delete(listener);
  };
}

function doSpeak(text: string): void {
  const synth = window.speechSynthesis;
  const normalizedText = text.trim();
  const voices = ensureVoicesLoaded();

  if (!normalizedText) return;

  if (voices.length === 0) {
    pendingVoicesText = normalizedText;
    lastSpeechEvent = 'waiting-for-voices';
    emitDebugState();
    window.setTimeout(() => {
      if (pendingVoicesText === normalizedText) {
        pendingVoicesText = null;
        doSpeak(normalizedText);
      }
    }, 400);
    return;
  }

  if (queuedSpeakTimer !== null) {
    window.clearTimeout(queuedSpeakTimer);
    queuedSpeakTimer = null;
  }

  lastSpeechError = null;
  lastSpeechEvent = 'queued';
  activeUtterance = new SpeechSynthesisUtterance(normalizedText);
  activeUtterance.lang = isChromeBrowser() ? 'pt-BR' : 'pt-PT';
  activeUtterance.rate = 0.8;
  activeUtterance.pitch = 1.1;

  const preferredVoice = getPreferredVoice();
  if (preferredVoice && !isChromeBrowser()) {
    activeUtterance.voice = preferredVoice;
    activeUtterance.lang = preferredVoice.lang;
  } else if (preferredVoice) {
    activeUtterance.lang = preferredVoice.lang;
  }

  activeUtterance.onstart = () => {
    lastSpeechEvent = 'start';
    emitDebugState();
  };

  activeUtterance.onend = () => {
    activeUtterance = null;
    lastSpeechEvent = 'end';
    emitDebugState();
  };

  activeUtterance.onerror = (event) => {
    activeUtterance = null;
    lastSpeechEvent = 'error';
    lastSpeechError = event.error;
    emitDebugState();
  };

  synth.resume();
  synth.speak(activeUtterance);
  emitDebugState();
}

export function speak(text: string): void {
  if (!('speechSynthesis' in window)) return;

  const synth = window.speechSynthesis;
  const normalizedText = text.trim();

  if (!normalizedText) return;

  if (queuedSpeakTimer !== null) {
    window.clearTimeout(queuedSpeakTimer);
    queuedSpeakTimer = null;
  }

  if (synth.speaking || synth.pending) {
    lastSpeechEvent = 'cancel';
    synth.cancel();
    queuedSpeakTimer = window.setTimeout(() => doSpeak(normalizedText), 150);
    emitDebugState();
    return;
  }

  doSpeak(normalizedText);
}

export function testSpeech(): void {
  speak('Ola, teste de voz do LeBem. Esta e a voz do leitor.');
}
